import React from "react";
import { useNavigate } from "react-router-dom";
import api from "../api"; // Assure-toi que ton fichier api.js est bien configuré
import "."; // Pour le style

const Dashboard = () => {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await api.post("/logout");
      localStorage.removeItem("authToken");
      navigate("/login"); // Rediriger vers la page de connexion
    } catch (error) {
      console.error("Erreur lors de la déconnexion:", error.response?.data);
    }
  };

  return (
    <div className="dashboard">
      {/* En-tête */}
      <header className="dashboard-header">
        <h1>Bienvenue sur ReceiptFlow</h1>
        <p>Gérez vos dépenses facilement.</p>
      </header>

      {/* Section des services */}
      <section className="services-section">
        <h2>Nos Services</h2>
        <div className="services-grid">
          <div className="service-card">
            <img src="/images/service1.jpg" alt="Service 1" className="service-image" />
            <h3>Upload vos reçus</h3>
            <p>Téléchargez vos reçus pour suivre vos dépenses.</p>
          </div>
          <div className="service-card">
            <img src="/images/service2.jpg" alt="Service 2" className="service-image" />
            <h3>Visualisez vos dépenses</h3>
            <p>Analysez vos habitudes de consommation.</p>
          </div>
          <div className="service-card">
            <img src="/images/service3.jpg" alt="Service 3" className="service-image" />
            <h3>Reconnaissance automatique</h3>
            <p>Classifiez vos dépenses automatiquement.</p>
          </div>
        </div>
      </section>

      {/* Bouton de déconnexion */}
      <button onClick={handleLogout} className="logout-button">
        Déconnexion
      </button>
    </div>
  );
};

export default Dashboard;
